item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '
$taskRoot = '"'D:\\tx-harness-participants\\pilot-codex-T04-r1'
"'$trades = @(Import-Csv -LiteralPath "$taskRoot'"\\inputs\\trades.csv\")
"'$rates = Get-Content -LiteralPath "$taskRoot'"\\inputs\\rates.json\" -Raw | ConvertFrom-Json -AsHashtable
if ("'$rates.base_currency -ne '"'CNY') { throw 'Invalid target currency' }
if (@("'$trades.trade_id | Sort-Object -Unique).Count -ne $trades.Count) { throw '"'Duplicate trade_id' }
"'$ledger = @(
foreach ($t in $trades) {
    $included = $t.status -eq '"'settled'
    "'$n = '"'-'; "'$d = '"'-'; "'$cents = [long]0
    if ($included) {
        $r = $rates.rates[$t.trade_date][$t.currency]
        if ($null -eq $r) { throw "Missing rate for $($t.trade_id)" }
        $n = [long]$r.numerator; $d = [long]$r.denominator
        if ($d -le 0 -or $n -lt 0) { throw '"'Invalid rational rate' }
        "'$product = [System.Numerics.BigInteger]::Parse($t.amount_minor) * [System.Numerics.BigInteger]$n
        $cents = [long]([System.Numerics.BigInteger]::Divide(2 * $product + $d, 2 * [System.Numerics.BigInteger]$d))
    } elseif ($t.status -ne '"'pending') { throw 'Unknown status' }
    [pscustomobject][ordered]@{trade_id="'$t.trade_id;trade_date=$t.trade_date;currency=$t.currency;amount_minor=$t.amount_minor;status=$t.status;included=$included.ToString().ToLowerInvariant();rate_numerator=$n;rate_denominator=$d;cny_cents=$cents}
})
$selected = @($ledger | Where-Object included -eq '"'true')
"'$total = [long](($selected | Measure-Object cny_cents -Sum).Sum)
$byCurrency = @($selected | Group-Object currency | Sort-Object Name | ForEach-Object { [ordered]@{currency=$_.Name;trade_count=$_.Count;cny_cents=[long](($_.Group | Measure-Object cny_cents -Sum).Sum)} })
$byDate = @($selected | Group-Object trade_date | Sort-Object Name | ForEach-Object { [ordered]@{date=$_.Name;trade_count=$_.Count;cny_cents=[long](($_.Group | Measure-Object cny_cents -Sum).Sum)} })
$summary = [ordered]@{currency='"'CNY';included_count="'$selected.Count;excluded_count=$ledger.Count-$selected.Count;total_cny_cents=$total;by_currency=$byCurrency;by_date=$byDate}
$incident = [ordered]@{initial_blocker=[ordered]@{code='"'MISSING_REQUIRED_INPUT';missing_file='rates.json'};recovery=[ordered]@{input='rates.json';method='provided_by_user'};assumptions=@();used_rate_dates=@("'$selected.trade_date | Sort-Object -Unique)}
$ledger | Export-Csv -LiteralPath "$taskRoot'"\\outputs\\conversion_ledger.csv\" -NoTypeInformation -Encoding utf8
"'$summary | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$taskRoot'"\\outputs\\summary.json\" -Encoding utf8
"'$incident | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$taskRoot'"\\outputs\\incident.json\" -Encoding utf8
Get-Content -LiteralPath \""'$taskRoot'"\\outputs\\conversion_ledger.csv\"
Get-Content -LiteralPath \""'$taskRoot'"\\outputs\\summary.json\"
"
